    c4 = chi4_arr(n)
    Zx = build_T(c4, n)
    Lx = current_of(log_upper(Zx), n)
    dev_chi = float(np.max(np.abs(Lx - build_T(c4 * lamc, n))))
    rK = np.zeros(n + 1)
    for d in range(1, n + 1):
        rK[d::d] += c4[d]
    ZK = Z @ Zx
    dev_rk = float(np.max(np.abs(ZK - build_T(rK, n))))
    LK = current_of(log_upper(ZK), n)
