    C_ctrl, _, _, _ = correlator(n, lamc, psi_ctrl, tg_ctrl)
    dmax = 0.0
    dvec = np.log(np.arange(1, n + 1))
    for t in (0.0, 0.8, 2.4):
        ph = np.exp(1j * t * dvec)
